import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService, LoginRequest } from '../../../core/services/auth.service';

@Component({
  selector: 'app-login',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.scss']
})
export class LoginComponent {
  form: FormGroup;
  isLoading = false;
  hasError = false;
  errorMessage = '';

  constructor(
    private fb: FormBuilder,
    private authService: AuthService,
    private router: Router
  ) {
    this.form = this.fb.group({
      email: ['', [Validators.required, Validators.email]],
      password: ['', [Validators.required, Validators.minLength(6)]]
    });
  }

  get email() {
    return this.form.get('email');
  }

  get password() {
    return this.form.get('password');
  }

  login(): void {
    if (this.form.invalid) {
      return;
    }

    this.isLoading = true;
    this.hasError = false;

    const credentials: LoginRequest = {
      email: this.form.value.email,
      senha: this.form.value.password as string
    };

    this.authService.login(credentials).subscribe({
      next: () => {
        this.isLoading = false;
        const userData = this.authService.getUserData();
        const redirectTo = userData?.role === 1 ? '/admin' : '/dashboard';
        this.router.navigate([redirectTo]);
      },
      error: (error: any) => {
        this.isLoading = false;
        this.hasError = true;
        this.errorMessage = error?.error?.message || 'Erro ao fazer login. Verifique suas credenciais.';
      }
    });
  }

  goToRegister(): void {
    this.router.navigate(['/register']);
  }
}
<div class="login-container">
  <div class="login-card">
    <h1>{{ 'login.title' | t }}</h1>
    <p class="subtitle">{{ 'login.subtitle' | t }}</p>

    <form [formGroup]="form" (ngSubmit)="login()" class="login-form">
      <div class="form-group">
        <label for="email">{{ 'login.email_label' | t }}</label>
        <input
          id="email"
          type="email"
          formControlName="email"
          class="form-input"
          placeholder="seu@email.com"
          [class.error]="email?.invalid && email?.touched"
        />
        <span class="error-message" *ngIf="email?.invalid && email?.touched">
          <span *ngIf="email?.errors?.['required']">Email é obrigatório</span>
          <span *ngIf="email?.errors?.['email']">Email inválido</span>
        </span>
      </div>

      <div class="form-group">
        <label for="password">{{ 'login.password_label' | t }}</label>
        <input
          id="password"
          type="password"
          formControlName="password"
          class="form-input"
          placeholder="••••••••"
          [class.error]="password?.invalid && password?.touched"
        />
        <span class="error-message" *ngIf="password?.invalid && password?.touched">
          <span *ngIf="password?.errors?.['required']">Senha é obrigatória</span>
          <span *ngIf="password?.errors?.['minlength']">Mínimo 6 caracteres</span>
        </span>
      </div>

      <div class="alert alert-error" *ngIf="hasError">
        {{ errorMessage }}
      </div>

      <button
        type="submit"
        class="btn btn-primary"
        [disabled]="form.invalid || isLoading"
      >
        <span *ngIf="!isLoading">Entrar</span>
        <span *ngIf="isLoading">Entrando...</span>
      </button>
    </form>

    <div class="form-footer">
      <p>Não tem uma conta? <a href="javascript:void(0)" (click)="goToRegister()">Criar nova</a></p>
    </div>
  </div>
</div>
